	private static void initContentHandlerMaps() {
		Dictionary<Class<object>, ContentHandler<object>> classMap = new();
		Dictionary<string, ContentHandler<object>> typeMap = new();

		/* @SuppressWarnings("rawtypes") */
		List<ContentHandler> handlers = ClassSearcher.getInstances(typeof(ContentHandler));
		foreach (ContentHandler<object> ch in handlers) {
			string contentType = ch.getContentType();
			if (typeMap.put(contentType, ch) != null) {
				Msg.error(typeof(DomainObjectAdapter),
					"Multiple content handlers discovered for content type: " + contentType);
			}
			if (!(ch is LinkHandler<object>)) {
				Class<DomainObjectAdapter> contentClass = ch.getDomainObjectClass();
				if (classMap.put(contentClass, ch) != null) {
					Msg.error(typeof(DomainObjectAdapter),
						"Multiple content handlers discovered for content class: " +
							contentClass.getSimpleName());
				}
			}
		}

		contentHandlerClassMap = classMap;
		contentHandlerTypeMap = typeMap;
